/**
 * Per-script configuration for the 9AM NUI layer.
 *
 * This is the ONE kit file you are expected to edit after installing.
 * `bunx 9am-ui check` deliberately skips it — everything else should stay as
 * shipped so fixes keep flowing down from the registry.
 */
export const nuiConfig = {
  /**
   * Resource name used to build the `https://<resource>/<callback>` URL.
   *
   * In CEF this is read from `window.GetParentResourceName()` and this value is
   * never touched; it only applies when the app runs as a plain browser page
   * (`bun run start`), where it just needs to be something recognisable in the
   * network tab.
   */
  resourceName: "9am-script",

  /** localStorage key the theme toggle persists to. Namespaced per script so
   *  two 9AM NUIs open in the same CEF context can't stomp each other. */
  themeStorageKey: "9am-script:theme",

  /** Theme used on first run, before the player has toggled anything. */
  defaultTheme: "dark" as "light" | "dark",
} as const;

// Will return whether the current environment is in a regular browser
// and not CEF
export const isEnvBrowser = (): boolean => !window.invokeNative;


// Basic no operation function
export const noop = () => {};

import { isEnvBrowser } from "@/utils/misc";
import { nuiConfig } from "@/nui.config";

/**
 * Simple wrapper around fetch API tailored for CEF/NUI use. This abstraction
 * can be extended to include AbortController if needed or if the response isn't
 * JSON. Tailor it to your needs.
 *
 * @param eventName - The endpoint eventname to target
 * @param data - Data you wish to send in the NUI Callback
 * @param mockData - Mock data to be returned if in the browser
 *
 * @return returnData - A promise for the data sent back by the NuiCallbacks CB argument
 */

export async function fetchNui<T = unknown>(
  eventName: string,
  data?: unknown,
  mockData?: T,
): Promise<T> {
  const options = {
    method: "post",
    headers: {
      "Content-Type": "application/json; charset=UTF-8",
    },
    body: JSON.stringify(data),
    signal: AbortSignal.timeout(10000),
  };

  if (isEnvBrowser() && mockData) return mockData;

  const resourceName = window.GetParentResourceName
    ? window.GetParentResourceName()
    : nuiConfig.resourceName;

  try {
    const resp = await fetch(`https://${resourceName}/${eventName}`, options);

    const respFormatted = await resp.json();

    return respFormatted;
  } catch (error) {
    console.error(`fetchNui: request "${eventName}" failed:`, error);
    // Safe fallback so awaiting call sites never hang or reject uncaught:
    // array consumers get an empty-compatible array, everyone else gets a failure result.
    if (Array.isArray(mockData)) return mockData;
    return { success: false, message: "Request failed" } as unknown as T;
  }
}

import { isEnvBrowser } from "./misc";

interface DebugEvent<T = unknown> {
  action: string;
  data: T;
}

/**
 * Emulates dispatching an event using SendNuiMessage in the lua scripts.
 * This is used when developing in browser
 *
 * @param events - The event you want to cover
 * @param timer - How long until it should trigger (ms)
 */
export const debugData = <P>(events: DebugEvent<P>[], timer = 50): void => {
  if (import.meta.env.MODE === "development" && isEnvBrowser()) {
    for (const event of events) {
      setTimeout(() => {
        window.dispatchEvent(
          new MessageEvent("message", {
            data: {
              action: event.action,
              data: event.data,
            },
          }),
        );
      }, timer);
    }
  }
};

import { MutableRefObject, useEffect, useRef } from "react";
import { noop } from "@/utils/misc";

interface NuiMessageData<T = unknown> {
  action: string;
  data: T;
}

type NuiHandlerSignature<T> = (data: T) => void;

/**
 * A hook that manage events listeners for receiving data from the client scripts
 * @param action The specific `action` that should be listened for.
 * @param handler The callback function that will handle data relayed by this hook
 *
 * @example
 * useNuiEvent<{visibility: true, wasVisible: 'something'}>('setVisible', (data) => {
 *   // whatever logic you want
 * })
 *
 **/

export const useNuiEvent = <T = unknown>(
  action: string,
  handler: (data: T) => void,
) => {
  const savedHandler: MutableRefObject<NuiHandlerSignature<T>> = useRef(noop);

  // Make sure we handle for a reactive handler
  useEffect(() => {
    savedHandler.current = handler;
  }, [handler]);

  useEffect(() => {
    const eventListener = (event: MessageEvent<NuiMessageData<T>>) => {
      if (!event.data || typeof event.data !== "object") return;
      const { action: eventAction, data } = event.data;

      if (savedHandler.current) {
        if (eventAction === action) {
          savedHandler.current(data);
        }
      }
    };

    window.addEventListener("message", eventListener);
    // Remove Event Listener on component cleanup
    return () => window.removeEventListener("message", eventListener);
  }, [action]);
};

/// <reference types="vite/client" />

export {}

// FiveM NUI globals injected by the CEF host. Optional because the app also
// runs as a plain browser page (bun run start) where neither is defined.
declare global {
  interface Window {
    invokeNative?: (...args: unknown[]) => void
    GetParentResourceName?: () => string
  }

  /** Compile-time flag from vite.config.ts `define`: true everywhere except
   *  `bun run production-build`, where dev-seed/mock-data paths are stripped. */
  const __DEV_SEED__: boolean
}
